contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount: amount of wei to deposit into c
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // balances before any interaction
        uint beforeTestBalance = address(this).balance;
        uint beforeCBalance = address(c).balance;

        // perform deposit to c
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // balances after deposit
        uint afterDepositTestBalance = address(this).balance;
        uint afterDepositCBalance = address(c).balance;

        // attempt withdrawAll and record whether it reverted
        bool withdrew;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrew = false;
        } else {
            withdrew = true;
        }

        // Single assert expressing the general rule described
        assert(
            (withdrew && address(this).balance == afterDepositTestBalance + depositAmount && address(c).balance + depositAmount == afterDepositCBalance)
            ||
            (!withdrew && address(this).balance == afterDepositTestBalance && address(c).balance >= afterDepositCBalance)
        );
    }

    receive() external payable {}
}

