// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint beforeTestBalance = address(this).balance;
        uint beforeCBalance = address(c).balance;
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint afterDepositTestBalance = address(this).balance;
        uint afterDepositCBalance = address(c).balance;
        bool withdrew;
        try c.withdrawAll() {
            withdrew = true;
        } catch {
            withdrew = false;
        }
        assertTrue((withdrew && address(this).balance == afterDepositTestBalance + depositAmount && address(c).balance + depositAmount == afterDepositCBalance)
            ||
            (!withdrew && address(this).balance == afterDepositTestBalance && address(c).balance >= afterDepositCBalance));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
